<?php
declare(strict_types=1);
const V_SCOPES=['application'=>'recruitment_applications','contact'=>'contact_inquiries','subscriber'=>'newsletter_subscribers','request'=>'privacy_requests'];
function v_confirm(PDO $pdo,array $user):void{c_super($user);$bucket=ip_hash('sensitive:'.$user['id']);$limit=$pdo->prepare('SELECT attempts,expires_at FROM auth_rate_limits WHERE bucket_key=?');$limit->execute([$bucket]);$attempts=$limit->fetch();if($attempts&&(int)$attempts['expires_at']>time()&&(int)$attempts['attempts']>=5){http_response_code(429);throw new DomainException('Too many failed sensitive confirmations. Try again in 15 minutes.');}if(!verify_current_code($pdo,(int)$user['id'],field('confirm_code'))){rate_limit($pdo,[$bucket=>5]);http_response_code(403);throw new DomainException('Confirm this sensitive action with your current private code.');}}
function v_subject(PDO $pdo,string $scope,int $id):array{if(!isset(V_SCOPES[$scope])){throw new DomainException('Choose a valid record type.');}$stmt=$pdo->prepare('SELECT * FROM '.V_SCOPES[$scope].' WHERE id=? FOR UPDATE');$stmt->execute([$id]);$row=$stmt->fetch();if(!$row){throw new DomainException('Record not found.');}return $row;}
function v_export(PDO $pdo,array $user,int $request):array{
 v_confirm($pdo,$user);$stmt=$pdo->prepare("SELECT * FROM privacy_requests WHERE id=? AND verified_at IS NOT NULL AND kind='access'");$stmt->execute([$request]);$r=$stmt->fetch();if(!$r){throw new DomainException('Choose an email-verified access request. Record any additional identity verification before release.');}
 $data=['request_reference'=>$r['reference'],'generated_at'=>gmdate('c'),'staff_review_required'=>'Review third-party information and applicable exemptions before securely releasing. Private evaluations and staff notes are excluded. Attachments require a separately reviewed secure transfer.'];
 $queries=['applications'=>'SELECT reference,role_id,form_version,full_name,email,age,location,availability,answers_json,public_status,notice_version,privacy_notice,acknowledged_at,received_at FROM recruitment_applications WHERE email_hash=?','contacts'=>'SELECT reference,full_name,email,category,subject,message,state,received_at FROM contact_inquiries WHERE email_hash=?','subscriptions'=>'SELECT email,state,topics_json,notice_version,requested_at,confirmed_at,unsubscribed_at FROM newsletter_subscribers WHERE email_hash=?'];
 foreach($queries as $key=>$sql){$stmt=$pdo->prepare($sql.' ORDER BY id LIMIT 501');$stmt->execute([$r['email_hash']]);$rows=$stmt->fetchAll();if(count($rows)>500){throw new DomainException('This subject has more than 500 records. Arrange a supervised export in bounded parts.');}$data[$key]=$rows;}
 audit($pdo,(int)$user['id'],'privacy.access_export',$request);return $data;
}
function v_action_privacy(PDO $pdo,array $user):array{
 c_super($user);$action=field('action');
 if($action==='retention_refresh'){
  v_confirm($pdo,$user);p_lock($pdo);try{$rows=$pdo->query("SELECT a.id,r.deadline,r.closed_at FROM recruitment_applications a JOIN recruitment_roles r ON r.id=a.role_id WHERE a.retention_due_at IS NULL AND a.outcome<>'selected' AND (r.closed_at IS NOT NULL OR r.deadline<=UTC_TIMESTAMP()) AND NOT EXISTS (SELECT 1 FROM privacy_controls c WHERE c.scope='application' AND c.subject_id=a.id AND c.anonymized_at IS NOT NULL) ORDER BY a.id LIMIT 100 FOR UPDATE")->fetchAll();$months=r_retention_months();foreach($rows as $row){$base=$row['closed_at']!==null?min($row['closed_at'],$row['deadline']):$row['deadline'];$stmt=$pdo->prepare('UPDATE recruitment_applications SET retention_due_at=DATE_ADD(?,INTERVAL ? MONTH) WHERE id=? AND retention_due_at IS NULL');$stmt->execute([$base,$months,$row['id']]);}audit($pdo,(int)$user['id'],'privacy.retention_refreshed');$pdo->commit();return ['Initialized up to 100 missing retention dates from closure/deadline. Existing dates were not extended; no information was deleted.'];}catch(Throwable $e){if($pdo->inTransaction()){$pdo->rollBack();}throw $e;}
 }
 if($action==='production_erase'){
  v_confirm($pdo,$user);if(field('production_review')!=='1'){throw new DomainException('Explicit production/contract and identity review is required.');}$request=(int)field('request_id');$stmt=$pdo->prepare("SELECT id FROM privacy_requests WHERE id=? AND kind='delete' AND verified_at IS NOT NULL AND state IN ('Verified','In Progress')");$stmt->execute([$request]);if(!$stmt->fetchColumn()){throw new DomainException('Choose an active verified deletion request and manually verify its relationship to the production content.');}$reason=c_text(field('reason'),1000,true);$pdo->beginTransaction();try{$item=c_item($pdo,(int)field('item_id'),true);if(!$item['archived']||!hash_equals($item['slug'],field('typed_reference'))){throw new DomainException('Archive the production record first and type its exact slug.');}$stmt=$pdo->prepare("UPDATE cms_revisions SET title='Removed production content',excerpt='',body='',cover_asset_id=NULL,alt_text='',caption='',credit='',video_url='',seo_title='',seo_description='',character_json='[]' WHERE item_id=?");$stmt->execute([$item['id']]);$stmt=$pdo->prepare("UPDATE cms_events SET note='' WHERE item_id=?");$stmt->execute([$item['id']]);$stmt=$pdo->prepare('UPDATE cms_items SET slug=?,scheduled_revision_id=NULL,scheduled_at=NULL WHERE id=?');$stmt->execute(['removed-'.bin2hex(random_bytes(16)),$item['id']]);$stmt=$pdo->prepare('INSERT INTO privacy_events(request_id,actor_id,actor_name,note) VALUES (?,?,?,?)');$stmt->execute([$request,$user['id'],$user['username'],'Reviewed production content erasure #'.$item['id'].': '.$reason]);audit($pdo,(int)$user['id'],'privacy.production_erased',(int)$item['id']);$pdo->commit();return ['Archived production snapshots scrubbed after review. Repeat for other matching records; orphan image bytes need separate removal.'];}catch(Throwable $e){if($pdo->inTransaction()){$pdo->rollBack();}throw $e;}
 }
 if($action==='asset_remove'){
  v_confirm($pdo,$user);$id=(int)field('asset_id');if(field('typed_reference')!==(string)$id){throw new DomainException('Type the exact image ID.');}c_text(field('reason'),1000,true);$pdo->beginTransaction();try{$stmt=$pdo->prepare('SELECT * FROM media_assets WHERE id=? FOR UPDATE');$stmt->execute([$id]);$asset=$stmt->fetch();if(!$asset){throw new DomainException('Image asset not found.');}$stmt=$pdo->prepare("SELECT id FROM cms_revisions WHERE cover_asset_id=? OR JSON_UNQUOTE(JSON_EXTRACT(character_json,'$.portrait_id'))=? LIMIT 1");$stmt->execute([$id,(string)$id]);if($stmt->fetchColumn()){throw new DomainException('This asset is referenced by a current or historical revision. Review and erase the appropriate archived content first.');}if(!preg_match('/\A[a-f0-9]{64}\z/D',$asset['storage_key'])){throw new DomainException('Invalid image key.');}$dir=r_storage().'/cms';if(is_link($dir)){throw new DomainException('Refusing a symbolic-link media directory.');}foreach([480,960,1600] as $size){$path=$dir.'/'.$asset['storage_key'].'-'.$size.'.jpg';if(is_link($path)){throw new DomainException('Refusing a symbolic-link image file.');}if(is_file($path)&&!@unlink($path)){throw new DomainException('One or more orphan variants could not be removed. Retry after checking storage permissions.');}}$stmt=$pdo->prepare('DELETE FROM media_assets WHERE id=?');$stmt->execute([$id]);audit($pdo,(int)$user['id'],'privacy.orphan_image_removed',$id);$pdo->commit();return ['Unreferenced optimized image variants removed. Other archives/backups require separate retention review.'];}catch(Throwable $e){if($pdo->inTransaction()){$pdo->rollBack();}throw $e;}
 }
 if($action==='files_remove'){v_confirm($pdo,$user);$dir=r_storage();$rows=$pdo->query("SELECT * FROM privacy_file_deletions WHERE state IN ('pending','failed') ORDER BY id LIMIT 20")->fetchAll();foreach($rows as $row){if(!preg_match('/\A[a-f0-9]{64}\.bin\z/D',$row['storage_key'])){continue;}$path=$dir.'/'.$row['storage_key'];$ok=!file_exists($path)||(!is_link($path)&&@unlink($path));$stmt=$pdo->prepare('UPDATE privacy_file_deletions SET state=?,attempts=attempts+1 WHERE id=?');$stmt->execute([$ok?'removed':'failed',$row['id']]);}audit($pdo,(int)$user['id'],'privacy.files_removed');return ['Processed up to 20 pending attachment deletions. Check for failed files before considering cleanup complete.'];}
 if($action==='request_update'){
  $id=(int)field('request_id');$note=c_text(field('note'),2000,true);$state=field('state');if(!in_array($state,['In Progress','Resolved','Declined'],true)){throw new DomainException('Choose a request status.');}
  $stmt=$pdo->prepare('SELECT * FROM privacy_requests WHERE id=?');$stmt->execute([$id]);$r=$stmt->fetch();if(!$r||!$r['verified_at']){throw new DomainException('Email must be verified before processing.');}$pdo->beginTransaction();try{$stmt=$pdo->prepare('UPDATE privacy_requests SET state=? WHERE id=?');$stmt->execute([$state,$id]);$stmt=$pdo->prepare('INSERT INTO privacy_events(request_id,actor_id,actor_name,note) VALUES (?,?,?,?)');$stmt->execute([$id,$user['id'],$user['username'],$state.': '.$note]);audit($pdo,(int)$user['id'],'privacy.request_updated',$id);$pdo->commit();return ['Privacy request updated. A status change does not itself delete or release information.'];}catch(Throwable $e){$pdo->rollBack();throw $e;}
 }
 v_confirm($pdo,$user);$scope=field('scope');$id=(int)field('subject_id');$reason=c_text(field('reason'),1000,true);
 p_lock($pdo);try{
 $row=v_subject($pdo,$scope,$id);$stmt=$pdo->prepare('INSERT IGNORE INTO privacy_controls(scope,subject_id) VALUES (?,?)');$stmt->execute([$scope,$id]);$stmt=$pdo->prepare('SELECT * FROM privacy_controls WHERE scope=? AND subject_id=? FOR UPDATE');$stmt->execute([$scope,$id]);$control=$stmt->fetch();
 if($action==='legal_hold'){$hold=field('hold')==='1';$stmt=$pdo->prepare('UPDATE privacy_controls SET legal_hold=?,hold_reason=? WHERE scope=? AND subject_id=?');$stmt->execute([(int)$hold,$reason,$scope,$id]);audit($pdo,(int)$user['id'],'privacy.hold_'.($hold?'set':'released'),$id,$scope);$pdo->commit();return ['Hold updated; it does not approve indefinite retention without a documented basis.'];}
 if($action!=='anonymize'){throw new DomainException('Unknown privacy action.');}if($control['legal_hold']){throw new DomainException('This record is under legal hold. Review and release the hold separately if appropriate.');}if($control['anonymized_at']){throw new DomainException('This record was already anonymized.');}
 $identifier=$row['reference']??$row['email'];if(!hash_equals($identifier,field('typed_reference'))){throw new DomainException('Type the exact current reference or subscriber email to confirm anonymization.');}
 $request=(int)field('request_id');$verified=false;if($request){$stmt=$pdo->prepare("SELECT id FROM privacy_requests WHERE id=? AND kind='delete' AND verified_at IS NOT NULL AND email_hash=? AND state IN ('Verified','In Progress')");$stmt->execute([$request,$row['email_hash']]);$verified=(bool)$stmt->fetchColumn();if(!$verified){throw new DomainException('The deletion request is not verified, active or associated with this email.');}}
 $due=false;
 if($scope==='application'){$due=$row['outcome']!=='selected'&&$row['retention_due_at']!==null&&strtotime($row['retention_due_at'].' UTC')<=time();if($row['outcome']==='selected'&&(!$verified||field('production_review')!=='1')){throw new DomainException('Selected production records need a verified deletion request and explicit production/contract policy review.');}}
 elseif($scope==='contact'){$due=in_array($row['state'],['Resolved','Closed'],true)&&$row['retention_due_at']!==null&&strtotime($row['retention_due_at'].' UTC')<=time();}
 elseif($scope==='subscriber'){$due=($row['state']==='pending'&&strtotime($row['requested_at'].' UTC')<time()-7*86400)||($row['state']==='unsubscribed'&&strtotime($row['unsubscribed_at'].' UTC')<time()-30*86400);}
 else{$due=(in_array($row['state'],['Resolved','Declined'],true)&&strtotime($row['created_at'].' UTC')<time()-90*86400)||($row['state']==='Awaiting Verification'&&strtotime($row['created_at'].' UTC')<time()-7*86400);}
 if(!$verified&&!$due){throw new DomainException('A matching verified deletion request or an expired applicable retention period is required.');}
 $tombstone=bin2hex(random_bytes(32));
 if($scope==='application'){
  $stmt=$pdo->prepare("SELECT n.id FROM audition_notifications n JOIN audition_appointments b ON b.id=n.appointment_id WHERE b.application_id=? AND n.state='sending' AND n.lease_until>? LIMIT 1");$stmt->execute([$id,time()]);if($stmt->fetchColumn()){throw new DomainException('An audition notice is sending. Retry after its lease completes.');}
  $stmt=$pdo->prepare('INSERT IGNORE INTO privacy_file_deletions(storage_key) SELECT storage_key FROM recruitment_attachments WHERE application_id=?');$stmt->execute([$id]);$stmt=$pdo->prepare('DELETE FROM recruitment_attachments WHERE application_id=?');$stmt->execute([$id]);$stmt=$pdo->prepare('DELETE FROM recruitment_tracking_challenges WHERE application_id=?');$stmt->execute([$id]);
  $stmt=$pdo->prepare("UPDATE audition_notifications n JOIN audition_appointments b ON b.id=n.appointment_id SET n.state='superseded',n.lease_until=NULL WHERE b.application_id=?");$stmt->execute([$id]);
  $stmt=$pdo->prepare("UPDATE audition_appointments SET state='cancelled',active_slot_id=NULL,version=version+1,public_snapshot='{}',private_note='',token_hash=NULL,token_expires=NULL,token_used_at=NULL WHERE application_id=?");$stmt->execute([$id]);
  foreach(["UPDATE audition_callbacks SET state='closed',private_note='' WHERE application_id=?","UPDATE audition_events SET private_note='',snapshot_json='{}' WHERE application_id=?","DELETE FROM evaluations WHERE application_id=? ORDER BY id DESC","UPDATE recruitment_events SET private_note='' WHERE application_id=?"] as $sql){$stmt=$pdo->prepare($sql);$stmt->execute([$id]);}
  $stmt=$pdo->prepare('UPDATE recruitment_delivery_log SET recipient_hash=? WHERE application_id=?');$stmt->execute([$tombstone,$id]);
  $stmt=$pdo->prepare("UPDATE recruitment_applications SET reference=?,full_name='Removed',email='',email_hash=?,age=18,location='',availability='',answers_json='{}',public_status='Closed',duplicate_flag=0,privacy_notice='',retention_due_at=NULL WHERE id=?");$stmt->execute(['SYA-'.strtoupper(bin2hex(random_bytes(16))),$tombstone,$id]);
 }elseif($scope==='contact'){
  $stmt=$pdo->prepare("SELECT id FROM contact_events WHERE inquiry_id=? AND delivery_state='sending' AND lease_until>? LIMIT 1");$stmt->execute([$id,time()]);if($stmt->fetchColumn()){throw new DomainException('A reply is sending. Retry after its lease completes.');}
  $stmt=$pdo->prepare("UPDATE contact_inquiries SET reference=?,full_name='Removed',email='',email_hash=?,subject='Removed',message='',notice_text='',state='Closed',assigned_to=NULL,follow_up_at=NULL,retention_due_at=NULL WHERE id=?");$stmt->execute(['CONTACT-'.strtoupper(bin2hex(random_bytes(16))),$tombstone,$id]);$stmt=$pdo->prepare("UPDATE contact_events SET body='',lease_until=NULL WHERE inquiry_id=?");$stmt->execute([$id]);
 }elseif($scope==='subscriber'){
  $stmt=$pdo->prepare("SELECT id FROM newsletter_deliveries WHERE subscriber_id=? AND state='sending' AND lease_until>? LIMIT 1");$stmt->execute([$id,time()]);if($stmt->fetchColumn()){throw new DomainException('A campaign email is sending. Retry after its lease completes.');}
  $stmt=$pdo->prepare("UPDATE newsletter_subscribers SET email='',email_hash=?,state='removed',topics_json='[]',notice_text='',unsubscribed_at=UTC_TIMESTAMP() WHERE id=?");$stmt->execute([$tombstone,$id]);$stmt=$pdo->prepare("UPDATE newsletter_events SET topics_json='[]' WHERE subscriber_id=?");$stmt->execute([$id]);$stmt=$pdo->prepare("UPDATE newsletter_deliveries SET state='skipped',lease_until=NULL WHERE subscriber_id=? AND state<>'accepted'");$stmt->execute([$id]);$stmt=$pdo->prepare("DELETE FROM communication_tokens WHERE subject_id=? AND kind IN ('confirm','manage')");$stmt->execute([$id]);
 }else{$stmt=$pdo->prepare("UPDATE privacy_requests SET email='',email_hash=? WHERE id=?");$stmt->execute([$tombstone,$id]);$stmt=$pdo->prepare("UPDATE privacy_events SET note='' WHERE request_id=?");$stmt->execute([$id]);$stmt=$pdo->prepare("DELETE FROM communication_tokens WHERE subject_id=? AND kind='rights'");$stmt->execute([$id]);}
 // Scrub pseudonymous delivery destinations too; no newsletter/contact message bodies are in this log.
 $stmt=$pdo->prepare('UPDATE recruitment_delivery_log SET recipient_hash=? WHERE recipient_hash=?');$stmt->execute([$tombstone,$row['email_hash']]);
 $stmt=$pdo->prepare('UPDATE privacy_controls SET anonymized_at=UTC_TIMESTAMP(),hold_reason=? WHERE scope=? AND subject_id=?');$stmt->execute([$reason,$scope,$id]);audit($pdo,(int)$user['id'],'privacy.anonymized',$id,$scope.'; reviewed request '.($request?:'retention'));
 if($request){$stmt=$pdo->prepare('INSERT INTO privacy_events(request_id,actor_id,actor_name,note) VALUES (?,?,?,?)');$stmt->execute([$request,$user['id'],$user['username'],'Anonymized '.$scope.' record #'.$id.'. Basis/review: '.$reason]);}
 $pdo->commit();return ['Record anonymized and private access revoked. Pending attachment files still require Process file deletions. Review related records and backup expiry separately.'];
 }catch(Throwable $e){if($pdo->inTransaction()){$pdo->rollBack();}throw $e;}
}
